import React, { useState, useEffect } from 'react';
import './DashboardJugador.css';
import MisEntrenamientos from './MisEntrenamientos';
import MisPartidos from './MisPartidos';
import MiAsistencia from './MiAsistencia';
import MisPagos from './MisPagos';
import MiQR from './MiQR';
import { getCurrentUser, getEstadisticasJugador } from '../../database/db';

function DashboardJugador() {
  const [activeTab, setActiveTab] = useState('entrenamientos');
  const [user, setUser] = useState(null);
  const [estadisticas, setEstadisticas] = useState({
    entrenamientosAsistidos: 0,
    partidosJugados: 0,
    totalDeuda: 0
  });
  const [menuOpen, setMenuOpen] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      console.log('Usuario actual:', currentUser);
      setUser(currentUser);
      
      if (currentUser && currentUser.id) {
        const stats = await getEstadisticasJugador(currentUser.id);
        console.log('Estadísticas del jugador:', stats);
        setEstadisticas({
          entrenamientosAsistidos: stats.entrenamientos_asistidos || stats.entrenamientosAsistidos || 0,
          partidosJugados: stats.partidos_jugados || stats.partidosJugados || 0,
          totalDeuda: stats.total_deuda || stats.totalDeuda || 0
        });
      }
    } catch (error) {
      console.error('Error cargando datos del jugador:', error);
    }
    setLoading(false);
  };

  const tabs = [
    { id: 'entrenamientos', nombre: 'Entrenamientos', icono: 'fa-futbol', mobileIcon: '⚽' },
    { id: 'partidos', nombre: 'Partidos', icono: 'fa-trophy', mobileIcon: '🏆' },
    { id: 'asistencia', nombre: 'Mi Asistencia', icono: 'fa-clipboard-list', mobileIcon: '📋' },
    { id: 'pagos', nombre: 'Mis Pagos', icono: 'fa-dollar-sign', mobileIcon: '💰' },
    { id: 'miqr', nombre: 'Mi QR', icono: 'fa-qrcode', mobileIcon: '📱' }
  ];

  const renderContent = () => {
    if (loading) {
      return (
        <div className="loading-container">
          <i className="fas fa-spinner fa-spin"></i>
          <p>Cargando tus datos...</p>
        </div>
      );
    }

    switch(activeTab) {
      case 'entrenamientos':
        return <MisEntrenamientos />;
      case 'partidos':
        return <MisPartidos />;
      case 'asistencia':
        return <MiAsistencia />;
      case 'pagos':
        return <MisPagos />;
      case 'miqr':
        return <MiQR />;
      default:
        return <MisEntrenamientos />;
    }
  };

  return (
    <div className="dashboard-jugador">
      {/* Mobile Header */}
      <div className="mobile-header-jugador">
        <div className="mobile-logo">
          <i className="fas fa-futbol"></i>
          <span>Academia Miguel Villalta</span>
        </div>
        <button className="menu-toggle" onClick={() => setMenuOpen(!menuOpen)}>
          <i className={`fas ${menuOpen ? 'fa-times' : 'fa-bars'}`}></i>
        </button>
      </div>

      {/* Sidebar Navigation */}
      <nav className={`jugador-nav ${menuOpen ? 'open' : ''}`}>
        <div className="nav-header-jugador">
          <div className="avatar">
            <i className="fas fa-user-circle"></i>
          </div>
          <div className="user-info">
            <h3>{user?.nombre || user?.Nombre || 'Jugador'}</h3>
            <p>#{user?.numero_camiseta || user?.NumeroCamiseta || '?'} - {user?.posicion || user?.Posicion || 'Sin posición'}</p>
          </div>
        </div>

        <div className="stats-mini">
          <div className="stat-mini">
            <span>✅ Asistencia</span>
            <strong>{estadisticas.entrenamientosAsistidos}</strong>
          </div>
          <div className="stat-mini">
            <span>⚽ Partidos</span>
            <strong>{estadisticas.partidosJugados}</strong>
          </div>
          <div className="stat-mini">
            <span>💰 Deuda</span>
            <strong>${estadisticas.totalDeuda.toLocaleString()}</strong>
          </div>
        </div>

        <div className="nav-tabs-jugador">
          {tabs.map(tab => (
            <button
              key={tab.id}
              className={`nav-tab-jugador ${activeTab === tab.id ? 'active' : ''}`}
              onClick={() => { setActiveTab(tab.id); setMenuOpen(false); }}
            >
              <i className={`fas ${tab.icono}`}></i>
              <span>{tab.nombre}</span>
              <span className="mobile-icon">{tab.mobileIcon}</span>
            </button>
          ))}
        </div>
      </nav>

      <div className="dashboard-content-jugador">
        {renderContent()}
      </div>
    </div>
  );
}

export default DashboardJugador;
